// Telegram button → approve/reject in Future Creative. Only allowed Telegram users may decide.
const q = $input.first().json.callback_query;
if (!q) return [];
const allowed = ($env.TELEGRAM_ALLOWED_USER_IDS || '').split(',').map((s) => s.trim()).filter(Boolean);
const token = $env.TELEGRAM_BOT_TOKEN;
const answer = (text) => this.helpers.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${token}/answerCallbackQuery`, body: { callback_query_id: q.id, text, show_alert: true }, json: true });
if (!allowed.includes(String(q.from.id))) { await answer('غير مصرح لك باتخاذ هذا القرار'); return []; }
const [kind, adId] = String(q.data || '').split(':');
if (!adId || !['a', 'r'].includes(kind)) return [];
return [{ json: { adId, decision: kind === 'a' ? 'approve' : 'reject', by: q.from.username || String(q.from.id), callbackId: q.id } }];

const r = $input.first().json;
const token = $env.TELEGRAM_BOT_TOKEN;
const cb = $('Check user & parse').first().json.callbackId;
const text = r.state ? `تم ✓ الحالة الآن: ${r.state}` : `تعذر: ${r.message || r.error || 'خطأ'}`;
await this.helpers.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${token}/answerCallbackQuery`, body: { callback_query_id: cb, text, show_alert: true }, json: true });
return [{ json: { text } }];
